     1→/*
     2→* Copyright (c) 2012-2014 Wind River Systems, Inc.
     3→*
     4→* SPDX-License-Identifier: Apache-2.0
     5→*
     6→* 移植期 A/B 对照版本：
     7→* - HELPER 直接写 BK7258 UART1 FIFO，绕过 Zephyr console。
     8→* - PRINTK/tick 走 Zephyr UART console。
     9→*
    10→* UART1 已验证寄存器：
    11→*   base        = 0x45830000
    12→*   fifo_status = base + 0x18
    13→*   fifo_port   = base + 0x1C
    14→*   TX full bit = bit16
    15→*/
    16→
    17→#include <zephyr/kernel.h>
    18→
    19→/* 使用 UART1: TX=P00, RX=P01（UART0 被 BKFIL 下载占用） */
    20→#define BK_UART1_BASE        0x45830000U
    21→#define BK_UART1_FIFO_PORT   (BK_UART1_BASE + 0x07U * 4U)
    22→#define BK_UART1_FIFO_STATUS (BK_UART1_BASE + 0x06U * 4U)
    23→#define BK_UART1_TX_FULL_BIT BIT(16)
    24→
    25→#define TX_FIFO_DATA_IN(bit8_val) ((uint32_t)(bit8_val) & 0xffU)
    26→
    27→static inline void bk_uart1_putc(char c)
    28→{
    29→	volatile uint32_t *fifo_port = (volatile uint32_t *)BK_UART1_FIFO_PORT;
    30→	volatile uint32_t *fifo_sts = (volatile uint32_t *)BK_UART1_FIFO_STATUS;
    31→	uint32_t timeout = 0xfffffU;
    32→
    33→	while (((*fifo_sts) & BK_UART1_TX_FULL_BIT) && timeout--) {
    34→	}
    35→
    36→	*fifo_port = TX_FIFO_DATA_IN((uint32_t)c);
    37→}
    38→
    39→static void bk_uart1_puts(const char *s)
    40→{
    41→	while (*s) {
    42→			if (*s == '\n') {
    43→					bk_uart1_putc('\r');
    44→			}
    45→			bk_uart1_putc(*s++);
    46→	}
    47→}
    48→
    49→int main(void)
    50→{
    51→	bk_uart1_puts("HELPER\n");
    52→	printk("PRINTK\n");
    53→
    54→	while (1) {
    55→			printk("tick\n");
    56→			k_sleep(K_MSEC(1000));
    57→	}
    58→
    59→	return 0;
    60→}

