     1→/dts-v1/;
     2→#include <arm/armv8-m.dtsi>
     3→
     4→/ {
     5→    model = "BK7258 EVB";
     6→    compatible = "beken,bk7258-evb";
     7→
     8→    chosen {
     9→        zephyr,flash = &flash0;
    10→        zephyr,sram  = &sram0;
    11→        /* zephyr,console = &uart1;  -- 等 UART 驱动完成后再启用 */
    12→        zephyr,console = &uart1;
    13→    };
    14→
    15→    cpus {
    16→        #address-cells = <1>;
    17→        #size-cells = <0>;
    18→
    19→        cpu@0 {
    20→            compatible = "arm,cortex-m33";
    21→            reg = <0>;
    22→            clock-frequency = <120000000>;  /* 来源: bk_idk CONFIG_DCO_FREQ */
    23→        };
    24→    };
    25→
    26→    uart1: serial@45830000 {
    27→        compatible = "beken,bk7258-uart";
    28→        reg = <0x45830000 0x100>;
    29→        current-speed = <115200>;
    30→        status = "okay";
    31→    };
    32→    /*
    33→     * ★★★ 内存映射（来源: bk_idk/include/soc/bk7258/reg_base.h）★★★
    34→     *
    35→     * 注意！BK7258 的真实地址：
    36→     *   - Flash 在 0x02000000（不是 0x0！0x0 是 ITCM）
    37→     *   - SRAM 在 0x28000000（不是 0x20000000！0x20000000 是 DTCM）
    38→     *
    39→     * hello_world 先用 SRAM0+SRAM1（连续 128 KB），跑得稳后再扩到 640 KB
    40→     */
    41→
    42→    /* 片内 Flash: Tuya normal bootloader 的 app 虚拟地址
    43→     * Beken code flash 每 32 字节数据追加 2 字节 CRC，
    44→     * app virtual 0x02010000 对应烧录 physical offset 0x11000。 */
    45→    flash0: flash@2010000 {
    46→        compatible = "soc-nv-flash";
    47→        reg = <0x02010000 0x003F0000>;    /* ~4 MB - 64K virtual app offset */
    48→    };
    49→
    50→    /* SRAM0+SRAM1 连续区段: 128 KB @ 0x28000000
    51→     * 来源: SOC_SRAM0_DATA_BASE(64K) + SOC_SRAM1_DATA_BASE(64K)
    52→     * 这两块在物理地址上紧邻，可以合并成一块。 */
    53→    sram0: memory@28000000 {
    54→        compatible = "mmio-sram";
    55→        reg = <0x28000000 0x00020000>;    /* 128 KB */
    56→    };
    57→
    58→    /* 时钟树（占位，等驱动完善后扩展）
    59→     * 来源: bk_idk CONFIG_XTAL_FREQ=26000000, CONFIG_DCO_FREQ=120000000 */
    60→    sysclk: clock-system {
    61→        compatible = "fixed-clock";
    62→        clock-frequency = <120000000>;
    63→        #clock-cells = <0>;
    64→    };
    65→};
    66→
    67→/* NVIC：3 位优先级（8 个优先级等级）
    68→ * 来源: bk_idk interrupts.c 用 PRI_GOURP_BITS_7_5，对应 3 位 preemption + 1 位 subpriority，
    69→ *       Zephyr 不使用分组，所以取 preemption 部分的位数 = 3。
    70→ *       (后续实际烧写验证时再校准) */
    71→&nvic {
    72→    arm,num-irq-priority-bits = <3>;
    73→};

