    19→
    20→    while (sys_read32(cfg->base + BK7258_UART_FIFO_STATUS_OFFSET) &
    21→            BK7258_UART_TX_FULL_BIT) {
    22→    }
    23→
    24→    sys_write32((uint32_t)c & 0xffU, cfg->base + BK7258_UART_FIFO_PORT_OFFSET);
    25→}
