   151→static inline void cursor_forward(unsigned int count)
   152→{
   153→	printk("\x1b[%uC", count);
   154→}
   155→
   156→static inline void cursor_backward(unsigned int count)
   157→{
   158→	printk("\x1b[%uD", count);
   159→}
