   186→        file_head->stream_flag = head->stream_flag;
   187→        file_head->length = UNI_HTONL(head->total_len);
   188→        if (payload && head->len) {
   189→            memcpy(file + SIZEOF(AI_FILE_HEAD_T), payload, head->len);
   190→        }
   191→        if (attr && (attr->flag == AI_HAS_ATTR)) {
   192→            rt = tuya_ai_basic_file(&(attr->value.file), file, payload_len, total_len, writer);
   193→        } else {
   194→            rt = tuya_ai_basic_file(NULL, file, payload_len, total_len, writer);
   195→        }
   196→        OS_FREE(file);
   197→    } else if (type == AI_PT_TEXT) {
   198→        payload_len = SIZEOF(AI_TEXT_HEAD_T) + head->len;
   199→        total_len = SIZEOF(AI_TEXT_HEAD_T) + head->total_len;
   200→        char *text = OS_MALLOC(payload_len);
   201→        TUYA_CHECK_NULL_RETURN(text, OPRT_MALLOC_FAILED);
   202→        memset(text, 0, payload_len);
