   207→        if (payload && head->len) {
   208→            memcpy(text + SIZEOF(AI_TEXT_HEAD_T), payload, head->len);
   209→        }
   210→        if (attr && (attr->flag == AI_HAS_ATTR)) {
   211→            rt = tuya_ai_basic_text(&(attr->value.text), text, payload_len, total_len, writer);
   212→        } else {
   213→            rt = tuya_ai_basic_text(NULL, text, payload_len, total_len, writer);
   214→        }
   215→        OS_FREE(text);
   216→    } else if (type == AI_PT_EVENT) {
   217→        payload_len = SIZEOF(AI_EVENT_HEAD_T) + head->len;
   218→        total_len = SIZEOF(AI_EVENT_HEAD_T) + head->total_len;
   219→        char *event = OS_MALLOC(payload_len);
   220→        TUYA_CHECK_NULL_RETURN(event, OPRT_MALLOC_FAILED);
   221→        memset(event, 0, payload_len);
   222→        AI_EVENT_HEAD_T *event_head = (AI_EVENT_HEAD_T *)event;
   223→        event_head->type = UNI_HTONS(id);
   224→        event_head->length = UNI_HTONL(head->total_len);
   225→        if (payload && head->len) {
   226→            memcpy(event + SIZEOF(AI_EVENT_HEAD_T), payload, head->len);
   227→        }
   228→        if (attr && (attr->flag == AI_HAS_ATTR)) {
   229→            rt = tuya_ai_basic_event(&(attr->value.event), event, payload_len, writer);
   230→        } else {
   231→            rt = tuya_ai_basic_event(NULL, event, payload_len, writer);
   232→        }
   233→        OS_FREE(event);
   234→    } else {
   235→        PR_ERR("unknow type:%d", type);
   236→        rt = OPRT_COM_ERROR;
   237→    }
   238→
   239→    if (rt != OPRT_OK) {
