   245→static void __ai_biz_thread_cb(void *args)
   246→{
   247→    OPERATE_RET rt = OPRT_OK;
   248→    uint32_t idx = 0, sidx = 0, kdx = 0;
   249→    while (!ai_basic_biz->terminate && tal_thread_get_state(ai_basic_biz->thread) == THREAD_STATE_RUNNING) {
   250→        if (!tuya_ai_client_is_ready()) {
   251→            tal_system_sleep(200);
   252→            continue;
   253→        }
   254→        tal_mutex_lock(ai_basic_biz->mutex);
   255→        uint16_t sent_ids[AI_MAX_SESSION_ID_NUM * AI_SESSION_MAX_NUM] = {0};
   256→        uint32_t sent_ids_count = 0;
   257→        for (idx = 0; idx < AI_SESSION_MAX_NUM; idx++) {
   258→            if (ai_basic_biz->session[idx].id[0] != 0) {
   259→                AI_SESSION_T *session = &ai_basic_biz->session[idx];
   260→                for (sidx = 0; sidx < session->cfg.send_num; sidx++) {
   261→                    uint16_t send_id = session->cfg.send[sidx].id;
   262→                    uint8_t already_sent = false;
   263→                    for (kdx = 0; kdx < sent_ids_count; kdx++) {
   264→                        if (sent_ids[kdx] == send_id) {
   265→                            already_sent = true;
   266→                            break;
   267→                        }
   268→                    }
   269→                    if (!already_sent) {
   270→                        sent_ids[sent_ids_count++] = send_id;
   271→                        AI_BIZ_SEND_DATA_T *send = &session->cfg.send[sidx];
   272→                        if (send->get_cb) {
   273→                            AI_BIZ_ATTR_INFO_T attr = {0};
   274→                            AI_BIZ_HEAD_INFO_T head = {0};
   275→                            char *payload = NULL;
   276→                            rt = send->get_cb(&attr, &head, &payload);
   277→                            if (rt != OPRT_OK) {
   278→                                continue;
   279→                            }
   280→                            tuya_ai_send_biz_pkt(send->id, &attr, send->type, &head, payload);
   281→                            if (send->free_cb) {
   282→                                send->free_cb(payload);
   283→                            }
   284→                        }
   285→                    }
   286→                }
   287→            }
   288→        }
   289→        tal_mutex_unlock(ai_basic_biz->mutex);
   290→        tal_system_sleep(AI_BIZ_TASK_DELAY);
   291→    }
   292→
   293→    PR_NOTICE("ai biz thread exit");
   294→    return;
   295→}
