    70→static OPERATE_RET __ai_agent_audio_recv(AI_BIZ_ATTR_INFO_T *attr, AI_BIZ_HEAD_INFO_T *head, char *data, void *usr_data)
    71→{
    72→
    73→    if (!head || !attr || !data) {
    74→        PR_ERR("invalid param");
    75→        return OPRT_COM_ERROR;
    76→    }
    77→
    78→    if (NULL == sg_ai.cbs.ai_agent_msg_cb) {
    79→        PR_ERR("msg_cb is NULL");
    80→        return OPRT_COM_ERROR;
    81→    }
    82→
    83→    uint32_t len = head->len;
    84→
    85→    switch (head->stream_flag) {
    86→    case AI_STREAM_START: {
    87→        AI_AGENT_MSG_T ai_msg = {
    88→            .type = AI_AGENT_MSG_TP_AUDIO_START,
    89→            .data_len = len,
    90→            .data = (uint8_t *)data,
    91→        };
    92→        sg_ai.cbs.ai_agent_msg_cb(&ai_msg);
    93→    } break;
    94→    case AI_STREAM_ING:
    95→    case AI_STREAM_END: {
    96→        AI_AGENT_MSG_T ai_msg;
    97→
    98→        if (len > 0) {
    99→            ai_msg.type = AI_AGENT_MSG_TP_AUDIO_DATA;
   100→            ai_msg.data_len = len;
   101→            ai_msg.data = (uint8_t *)data;
   102→
   103→            sg_ai.cbs.ai_agent_msg_cb(&ai_msg);
   104→        }
   105→
   106→        if (AI_STREAM_END == head->stream_flag) {
   107→            ai_msg.type = AI_AGENT_MSG_TP_AUDIO_STOP;
   108→            ai_msg.data_len = 0;
   109→            ai_msg.data = NULL;
   110→
   111→            sg_ai.cbs.ai_agent_msg_cb(&ai_msg);
   112→        }
   113→
   114→    } break;
   115→    default:
   116→        PR_ERR("unknown stream flag: %d", head->stream_flag);
   117→        break;
   118→    }
   119→
   120→    return OPRT_OK;
   121→}
