   263→static OPERATE_RET _parse_skill(cJSON *json)
   264→{
   265→    OPERATE_RET rt = OPRT_OK;
   266→
   267→    cJSON *node, *code;
   268→    const char *code_str;
   269→
   270→    // {"bizId":"xxx","bizType":"SKILL","eof":1,"data":{"code":"emo","skillContent":{"emotion":["NEUTRAL"],"text":["😐"]}}}
   271→    node = cJSON_GetObjectItem(json, "data");
   272→    code = cJSON_GetObjectItem(node, "code");
   273→    code_str = cJSON_GetStringValue(code);
   274→    if (!code_str)
   275→        return OPRT_OK;
   276→
   277→    PR_DEBUG("skill code: %s", code_str);
   278→
   279→    if (strcmp(code_str, "emo") == 0) {
   280→        cJSON *skillContent = cJSON_GetObjectItem(node, "skillContent");
   281→        rt = _parse_skill_emo(skillContent);
   282→    } else if (strcmp(code_str, "DeviceControl") == 0) {
   283→        cJSON *general = cJSON_GetObjectItem(node, "general");
   284→        rt = _parse_skill_device_control(general);
   285→    }
   286→
   287→    return rt;
   288→}
