   290→static OPERATE_RET __ai_agent_txt_recv(AI_BIZ_ATTR_INFO_T *attr, AI_BIZ_HEAD_INFO_T *head, char *data, void *usr_data)
   291→{
   292→    cJSON *json, *node;
   293→
   294→    if ((json = cJSON_Parse(data)) == NULL) {
   295→        return OPRT_OK;
   296→    }
   297→
   298→    // parse bizType
   299→    node = cJSON_GetObjectItem(json, "bizType");
   300→    const char *bizType = cJSON_GetStringValue(node);
   301→    // parse eof
   302→    node = cJSON_GetObjectItem(json, "eof");
   303→    uint8_t eof = cJSON_GetNumberValue(node);
   304→    // PR_DEBUG("bizType: %s, eof: %d", bizType, eof);
   305→
   306→    if (eof && strcmp(bizType, "ASR") == 0) {
   307→        // parse data.text
   308→        _parse_asr(json);
   309→    } else if (strcmp(bizType, "NLG") == 0) {
   310→        _parse_nlg(json, eof);
   311→    } else if (eof && strcmp(bizType, "SKILL") == 0) {
   312→        _parse_skill(json);
   313→    }
   314→
   315→    cJSON_Delete(json);
   316→    return OPRT_OK;
   317→}
