   319→static OPERATE_RET __ai_agent_event_recv(AI_EVENT_TYPE type, AI_SESSION_ID session_id, AI_EVENT_ID event_id,
   320→                                         uint8_t *attr, uint32_t attr_len)
   321→{
   322→    PR_DEBUG("recv event type:%d, session_id:%s, event_id:%s, attr_len: %d", type, session_id, event_id, attr_len);
   323→
   324→    // event type: 0-chat start, 1-chat stop, 2-data finish
   325→    if (type == AI_EVENT_START) {
   326→        // update stream event id
   327→        strncpy(sg_ai.stream_event_id, event_id, AI_UUID_V4_LEN);
   328→        sg_ai.stream_status = AI_AGENT_CHAT_STREAM_START;
   329→    } else if (type == AI_EVENT_PAYLOADS_END) {
   330→        // clear stream event id
   331→    } else if (type == AI_EVENT_END) {
   332→        // stream end
   333→    } else if (type == AI_EVENT_CHAT_BREAK || type == AI_EVENT_SERVER_VAD) {
   334→        if (strcmp(event_id, sg_ai.stream_event_id) != 0) {
   335→            PR_DEBUG("recv chat break or srv vad, but current stream is empty");
   336→            return OPRT_OK;
   337→        } else {
   338→            // clear stream event id
   339→            memset(sg_ai.stream_event_id, 0, AI_UUID_V4_LEN);
   340→        }
   341→    }
   342→
   343→    // notify event
   344→    if (sg_ai.cbs.ai_agent_event_cb) {
   345→        sg_ai.cbs.ai_agent_event_cb(type, event_id);
   346→    }
   347→
   348→    return OPRT_OK;
   349→}
