   545→/**
   546→ * @brief Uploads audio data to the AI service.
   547→ * @param data Pointer to the audio data buffer.
   548→ * @param len Length of the audio data in bytes.
   549→ * @return OPERATE_RET - OPRT_OK on success, or an error code on failure.
   550→ */
   551→OPERATE_RET ai_audio_agent_upload_data(uint8_t *data, uint32_t len)
   552→{
   553→    OPERATE_RET rt = OPRT_OK;
   554→
   555→    // send data use tuya_ai_send_biz_pkt, pcm
   556→    AI_BIZ_ATTR_INFO_T attr = {
