   558→        .type = AI_PT_AUDIO,
   559→        .value.audio =
   560→            {
   561→                .base.codec_type = AUDIO_CODEC_PCM,
   562→                .base.sample_rate = 16000,
   563→                .base.channels = AUDIO_CHANNELS_MONO,
