   567→                .option.session_id_list = NULL,
   568→            },
   569→    };
   570→    AI_BIZ_HEAD_INFO_T head = {
   571→        .value.audio =
   572→            {
   573→                .timestamp = tal_system_get_millisecond(),
   574→                .pts = 0,
   575→            },
