   138→static void __app_ai_audio_evt_inform_cb(AI_AUDIO_EVENT_E event, uint8_t *data, uint32_t len, void *arg)
   139→{
   140→#if defined(ENABLE_CHAT_DISPLAY) && (ENABLE_CHAT_DISPLAY == 1)
   141→#if !defined(ENABLE_GUI_STREAM_AI_TEXT) || (ENABLE_GUI_STREAM_AI_TEXT != 1)
   142→    static uint8_t *p_ai_text = NULL;
   143→    static uint32_t ai_text_len = 0;
   144→#endif
   145→#endif
   146→
   147→    switch (event) {
   148→    case AI_AUDIO_EVT_HUMAN_ASR_TEXT: {
   149→        if (len > 0 && data) {
   150→// send asr text to display
   151→#if defined(ENABLE_CHAT_DISPLAY) && (ENABLE_CHAT_DISPLAY == 1)
   152→            app_display_send_msg(TY_DISPLAY_TP_USER_MSG, data, len);
   153→#endif
   154→        }
   155→    } break;
   156→    case AI_AUDIO_EVT_AI_REPLIES_TEXT_START: {
   157→#if defined(ENABLE_CHAT_DISPLAY) && (ENABLE_CHAT_DISPLAY == 1)
   158→#if defined(ENABLE_GUI_STREAM_AI_TEXT) && (ENABLE_GUI_STREAM_AI_TEXT == 1)
   159→        app_display_send_msg(TY_DISPLAY_TP_ASSISTANT_MSG_STREAM_START, data, len);
   160→#else
   161→        if (NULL == p_ai_text) {
   162→            p_ai_text = tkl_system_psram_malloc(AI_AUDIO_TEXT_BUFF_LEN);
   163→            if (NULL == p_ai_text) {
   164→                return;
   165→            }
   166→        }
   167→
   168→        ai_text_len = 0;
   169→#endif
   170→#endif
   171→    } break;
   172→    case AI_AUDIO_EVT_AI_REPLIES_TEXT_DATA: {
   173→#if defined(ENABLE_CHAT_DISPLAY) && (ENABLE_CHAT_DISPLAY == 1)
   174→#if defined(ENABLE_GUI_STREAM_AI_TEXT) && (ENABLE_GUI_STREAM_AI_TEXT == 1)
   175→        app_display_send_msg(TY_DISPLAY_TP_ASSISTANT_MSG_STREAM_DATA, data, len);
   176→#else
   177→        memcpy(p_ai_text + ai_text_len, data, len);
   178→
   179→        ai_text_len += len;
   180→        if (ai_text_len >= AI_AUDIO_TEXT_SHOW_LEN) {
   181→            app_display_send_msg(TY_DISPLAY_TP_ASSISTANT_MSG, p_ai_text, ai_text_len);
   182→            ai_text_len = 0;
   183→        }
   184→#endif
   185→#endif
   186→    } break;
   187→    case AI_AUDIO_EVT_AI_REPLIES_TEXT_END: {
   188→#if defined(ENABLE_CHAT_DISPLAY) && (ENABLE_CHAT_DISPLAY == 1)
   189→#if defined(ENABLE_GUI_STREAM_AI_TEXT) && (ENABLE_GUI_STREAM_AI_TEXT == 1)
   190→        app_display_send_msg(TY_DISPLAY_TP_ASSISTANT_MSG_STREAM_END, data, len);
   191→#else
   192→        app_display_send_msg(TY_DISPLAY_TP_ASSISTANT_MSG, p_ai_text, ai_text_len);
   193→        ai_text_len = 0;
   194→#endif
   195→#endif
   196→    } break;
   197→    case AI_AUDIO_EVT_AI_REPLIES_TEXT_INTERUPT: {
   198→#if defined(ENABLE_GUI_STREAM_AI_TEXT) && (ENABLE_GUI_STREAM_AI_TEXT == 1)
   199→        app_display_send_msg(TY_DISPLAY_TP_ASSISTANT_MSG_STREAM_INTERRUPT, NULL, 0);
   200→#endif
   201→    } break;
   202→    case AI_AUDIO_EVT_AI_REPLIES_EMO: {
   203→        AI_AUDIO_EMOTION_T *emo;
   204→        PR_DEBUG("---> AI_MSG_TYPE_EMOTION");
   205→        emo = (AI_AUDIO_EMOTION_T *)data;
   206→        if (emo) {
   207→            if (emo->name) {
   208→                PR_DEBUG("emotion name:%s", emo->name);
   209→#if defined(ENABLE_CHAT_DISPLAY) && (ENABLE_CHAT_DISPLAY == 1)
   210→                app_display_send_msg(TY_DISPLAY_TP_EMOTION, (uint8_t *)emo->name, strlen(emo->name));
   211→#endif
   212→            }
   213→
   214→            if (emo->text) {
   215→                PR_DEBUG("emotion text:%s", emo->text);
   216→            }
   217→        }
   218→    } break;
   219→    case AI_AUDIO_EVT_ASR_WAKEUP: {
   220→        ai_audio_player_stop();
   221→        ai_audio_player_play_alert(AI_AUDIO_ALERT_WAKEUP);
   222→
   223→#if defined(ENABLE_LED) && (ENABLE_LED == 1)
   224→        TDL_LED_BLINK_CFG_T blink_cfg = {
   225→            .cnt = 2,
   226→            .start_stat = TDL_LED_ON,
   227→            .end_stat = TDL_LED_OFF,
   228→            .first_half_cycle_time = 100,
   229→            .latter_half_cycle_time = 100,
   230→        };
   231→
   232→        tdl_led_blink(sg_led_hdl, &blink_cfg);
   233→#endif
   234→
   235→#if defined(ENABLE_GUI_STREAM_AI_TEXT) && (ENABLE_GUI_STREAM_AI_TEXT == 1)
   236→        app_display_send_msg(TY_DISPLAY_TP_ASSISTANT_MSG_STREAM_END, data, len);
   237→#endif
   238→    } break;
   239→
   240→    default:
   241→        break;
   242→    }
   243→
   244→    return;
   245→}
