   310→static void __app_button_function_cb(char *name, TDL_BUTTON_TOUCH_EVENT_E event, void *argc)
   311→{
   312→    APP_CHAT_MODE_E work_mode = sg_chat_bot.work->mode;
   313→    PR_DEBUG("app button function cb, work mode: %d", work_mode);
   314→
   315→    // network status
   316→    netmgr_status_e status = NETMGR_LINK_DOWN;
   317→    netmgr_conn_get(NETCONN_AUTO, NETCONN_CMD_STATUS, &status);
   318→    if (status == NETMGR_LINK_DOWN) {
   319→        PR_DEBUG("network is down, ignore button event");
   320→        if (ai_audio_player_is_playing()) {
   321→            return;
   322→        }
   323→        ai_audio_player_play_alert(AI_AUDIO_ALERT_NOT_ACTIVE);
   324→        return;
   325→    }
   326→
   327→    switch (event) {
   328→    case TDL_BUTTON_PRESS_DOWN: {
   329→        if (work_mode == APP_CHAT_MODE_KEY_PRESS_HOLD_SINGLE) {
   330→            PR_DEBUG("button press down, listen start");
   331→#if defined(ENABLE_LED) && (ENABLE_LED == 1)
   332→            tdl_led_set_status(sg_led_hdl, TDL_LED_ON);
   333→#endif
   334→            ai_audio_manual_start_single_talk();
   335→        }
   336→    } break;
   337→    case TDL_BUTTON_PRESS_UP: {
   338→        if (work_mode == APP_CHAT_MODE_KEY_PRESS_HOLD_SINGLE) {
   339→            PR_DEBUG("button press up, listen end");
   340→#if defined(ENABLE_LED) && (ENABLE_LED == 1)
   341→            tdl_led_set_status(sg_led_hdl, TDL_LED_OFF);
   342→#endif
   343→            ai_audio_manual_stop_single_talk();
   344→        }
   345→    } break;
   346→    case TDL_BUTTON_PRESS_SINGLE_CLICK: {
   347→        if (work_mode == APP_CHAT_MODE_KEY_PRESS_HOLD_SINGLE) {
   348→            break;
   349→        }
   350→
   351→        if (sg_chat_bot.is_enable) {
   352→            ai_audio_player_stop();
   353→            ai_audio_player_play_alert(AI_AUDIO_ALERT_WAKEUP);
   354→            ai_audio_set_wakeup();
   355→        } else {
   356→            __app_chat_bot_enable(true);
   357→        }
   358→        PR_DEBUG("button single click");
   359→    } break;
   360→    default:
   361→        break;
   362→    }
   363→}
