   192→static uint8_t __is_client_registered(ai_monitor_client_t *client, uint8_t type)
   193→{
   194→    if (!client || type >= sizeof(client->registered_types) * 8 || !client->connected) {
   195→        return FALSE;
   196→    }
   197→    return (client->registered_types[type / 8] & (1 << (type % 8))) != 0;
   198→}
   199→
   200→static OPERATE_RET __client_register(ai_monitor_client_t *client, uint8_t type)
   201→{
   202→    if (!client || type >= sizeof(client->registered_types) * 8 || !client->connected) {
   203→        return OPRT_INVALID_PARM;
   204→    }
   205→
   206→    client->registered_types[type / 8] |= (1 << (type % 8));
   207→    PR_DEBUG("Client fd=%d registered type=%d", client->fd, type);
   208→    return OPRT_OK;
   209→}
