   241→static OPERATE_RET __handle_ping(ai_monitor_client_t *client, uint64_t client_ts, char *payload)
   242→{
   243→    OPERATE_RET rt = OPRT_OK;
   244→    uint64_t server_ts;
   245→
   246→    server_ts = client->last_ping_time = tal_time_get_posix_ms();
   247→    PR_DEBUG("Received ping from client fd=%d, client_ts=%llu", client->fd, client_ts);
   248→
   249→    // response ai pong
   250→    AI_SEND_PACKET_T pkt = {0};
   251→    pkt.type = AI_PT_PONG;
   252→    pkt.writer = &s_default_writer;
   253→    AI_MONITOR_WRITER_UPDATE(pkt.writer, client->fd,
   254→                             AI_MONITOR_DIR_ACK); // Update writer with client fd and ACK direction
   255→    // create pong attrs
   256→    uint32_t attr_idx = 0;
   257→    pkt.attrs[attr_idx++] = tuya_ai_create_attribute(AI_ATTR_CLIENT_TS, ATTR_PT_U64, &client_ts, SIZEOF(uint64_t));
   258→    pkt.attrs[attr_idx++] = tuya_ai_create_attribute(AI_ATTR_SERVER_TS, ATTR_PT_U64, &server_ts, SIZEOF(uint64_t));
   259→    pkt.count = attr_idx;
   260→    // TODO: check attr created
   261→    // if (!__ai_check_attr_created(&pkt)) {
   262→    //     return OPRT_MALLOC_FAILED;
   263→    // }
   264→    rt = tuya_ai_basic_pkt_send(&pkt);
   265→    if (rt != OPRT_OK) {
   266→        PR_ERR("Failed to send pong response, rt: %d", rt);
   267→        return rt;
   268→    }
   269→    PR_DEBUG("Handled ping for client fd=%d, client_ts=%llu, server_ts=%llu", client->fd, client_ts, server_ts);
   270→    return OPRT_OK;
   271→}
