   273→static OPERATE_RET __handle_event_filter(ai_monitor_client_t *client, AI_EVENT_ATTR_T *event)
   274→{
   275→    uint64_t user_data_bitmap = 0;
   276→
   277→    if (event->user_len != sizeof(uint64_t)) {
   278→        return OPRT_INVALID_PARM;
   279→    }
   280→    memcpy(&user_data_bitmap, event->user_data, sizeof(uint64_t));
   281→    UNI_NTOHLL(user_data_bitmap);
   282→    PR_DEBUG("Monitor Filter User data bitmap: 0x%016llx", user_data_bitmap);
   283→
   284→    __client_register_clear(client); // Clear all registered types
   285→    if (user_data_bitmap & (1ULL << AI_PT_VIDEO)) {
   286→        __client_register(client, AI_PT_VIDEO);
   287→    }
   288→    if (user_data_bitmap & (1ULL << AI_PT_AUDIO)) {
   289→        __client_register(client, AI_PT_AUDIO);
   290→    }
   291→    if (user_data_bitmap & (1ULL << AI_PT_IMAGE)) {
   292→        __client_register(client, AI_PT_IMAGE);
   293→    }
   294→    if (user_data_bitmap & (1ULL << AI_PT_FILE)) {
   295→        __client_register(client, AI_PT_FILE);
   296→    }
   297→    if (user_data_bitmap & (1ULL << AI_PT_TEXT)) {
   298→        __client_register(client, AI_PT_TEXT);
   299→    }
   300→    if (user_data_bitmap & (1ULL << AI_PT_EVENT)) {
   301→        __client_register(client, AI_PT_EVENT);
   302→    }
   303→    if (user_data_bitmap & (1ULL << AI_PT_CUSTOM_LOG)) {
   304→        __client_register(client, AI_PT_CUSTOM_LOG);
   305→        tal_log_add_output_term(AI_MONITOR_TAG, __log_output);
   306→    } else {
   307→        tal_log_del_output_term(AI_MONITOR_TAG);
   308→    }
   309→
   310→    return OPRT_OK;
   311→}
