   318→static OPERATE_RET __handle_event(ai_monitor_client_t *client, AI_EVENT_ATTR_T *event, char *payload)
   319→{
   320→    OPERATE_RET rt = OPRT_OK;
   321→    AI_EVENT_HEAD_T *head = (AI_EVENT_HEAD_T *)payload;
   322→    AI_EVENT_TYPE event_type = UNI_NTOHS(head->type);
   323→
   324→    PR_TRACE("Received event: session_id=%s, event_id=%s, user_len=%u, event_type=%d", event->session_id,
   325→             event->event_id, event->user_len, event_type);
   326→
   327→    if (event_type == AI_EVENT_MONITOR_FILTER) {
   328→        // Handle event filter
   329→        rt = __handle_event_filter(client, event);
   330→    } else if (event_type == AI_EVENT_MONITOR_ALG_CTRL) {
   331→        // Handle algorithm control event
   332→        rt = __handle_event_alg_ctrl(client, event);
   333→    } else {
   334→        // Unsupported event type
   335→        PR_ERR("Unsupported event type: %d", event_type);
   336→        rt = OPRT_NOT_SUPPORTED;
   337→    }
   338→
   339→    AI_SEND_PACKET_T pkt = {0};
   340→    pkt.type = AI_PT_EVENT;
   341→    pkt.writer = &s_default_writer;
   342→    AI_MONITOR_WRITER_UPDATE(pkt.writer, client->fd,
   343→                             AI_MONITOR_DIR_ACK); // Update writer with client fd and ACK direction
   344→    // create event attrs
   345→    uint32_t attr_idx = 0;
   346→    pkt.attrs[attr_idx++] =
   347→        tuya_ai_create_attribute(AI_ATTR_SESSION_ID, ATTR_PT_STR, event->session_id, strlen(event->session_id));
   348→    pkt.attrs[attr_idx++] =
   349→        tuya_ai_create_attribute(AI_ATTR_EVENT_ID, ATTR_PT_STR, event->event_id, strlen(event->event_id));
   350→    pkt.attrs[attr_idx++] =
   351→        tuya_ai_create_attribute(AI_ATTR_USER_DATA, ATTR_PT_BYTES, event->user_data, event->user_len);
   352→    pkt.count = attr_idx;
   353→    // TODO: check attr created
   354→    // if (!__ai_check_attr_created(&pkt)) {
   355→    //     return OPRT_MALLOC_FAILED;
   356→    // }
   357→    char resp_payload[sizeof(AI_EVENT_HEAD_T) + sizeof(uint32_t)] = {0};
   358→    ((AI_EVENT_HEAD_T *)resp_payload)->type = UNI_HTONS(event_type);
   359→    ((AI_EVENT_HEAD_T *)resp_payload)->length = UNI_HTONS(sizeof(uint32_t));
   360→    *((uint32_t *)(resp_payload + sizeof(AI_EVENT_HEAD_T))) = UNI_HTONL(rt); // Response data length
   361→    // Add response data
   362→    pkt.data = resp_payload;
   363→    pkt.len = sizeof(resp_payload);
   364→    rt = tuya_ai_basic_pkt_send(&pkt);
   365→    if (rt != OPRT_OK) {
   366→        PR_ERR("Failed to send event response, rt: %d", rt);
   367→        return rt;
   368→    }
   369→    return OPRT_OK;
   370→}
