   372→/**
   373→ * @brief Parse protocol frame
   374→ */
   375→static OPERATE_RET __parse_pkg(ai_monitor_client_t *client, char *data, uint32_t len)
   376→{
   377→    if (!client || !data || len < sizeof(AI_PAYLOAD_HEAD_T)) {
   378→        return OPRT_INVALID_PARM;
   379→    }
   380→
   381→    OPERATE_RET rt = OPRT_OK;
   382→    AI_PAYLOAD_HEAD_T *head = (AI_PAYLOAD_HEAD_T *)data;
   383→    AI_PACKET_PT type = head->type;
   384→    AI_ATTR_FLAG attr_flag = head->attribute_flag;
   385→    uint32_t attr_len = 0;
   386→    uint32_t offset = SIZEOF(AI_PAYLOAD_HEAD_T);
   387→    char *payload, *attr_buf;
   388→
   389→    if (type == AI_PT_PING) {
   390→        // parse attr
   391→        AI_ATTRIBUTE_T attr = {0};
   392→        uint64_t client_ts = 0;
   393→        if (head->attribute_flag != AI_HAS_ATTR) {
   394→            PR_ERR("ai ping packet has no attribute");
   395→            return OPRT_COM_ERROR;
   396→        }
   397→        memcpy(&attr_len, data + offset, SIZEOF(attr_len));
   398→        attr_len = UNI_NTOHL(attr_len);
   399→        offset += SIZEOF(attr_len);
   400→        attr_buf = data + offset;
   401→        offset += attr_len;
   402→        // parse attributes
   403→        while (offset < attr_len) {
   404→            memset(&attr, 0, SIZEOF(AI_ATTRIBUTE_T));
   405→            rt = tuya_ai_get_attr_value(attr_buf, &offset, &attr);
   406→            if (OPRT_OK != rt) {
   407→                PR_ERR("get attr value failed, rt:%d", rt);
   408→                return rt;
   409→            }
   410→
   411→            if (attr.type == AI_ATTR_CLIENT_TS) {
   412→                client_ts = attr.value.u64;
   413→            } else {
   414→                PR_ERR("unknown attr type: %d", attr.type);
   415→            }
   416→        }
   417→
   418→        // handle ping
   419→        return __handle_ping(client, client_ts, payload);
   420→    } else if (type == AI_PT_EVENT) {
   421→        AI_BIZ_ATTR_INFO_T attr_info;
   422→        memset(&attr_info, 0, SIZEOF(AI_BIZ_ATTR_INFO_T));
   423→        attr_info.flag = attr_flag;
   424→        attr_info.type = type;
   425→        if (attr_flag == AI_HAS_ATTR) {
   426→            memcpy(&attr_len, data + offset, SIZEOF(attr_len));
   427→            attr_len = UNI_NTOHL(attr_len);
   428→            offset += SIZEOF(attr_len);
   429→            attr_buf = data + offset;
   430→            rt = tuya_ai_parse_event_attr(attr_buf, attr_len, &attr_info.value.event);
   431→            if (OPRT_OK != rt) {
   432→                PR_ERR("parse event attr failed, rt:%d", rt);
   433→                return rt;
   434→            }
   435→            offset += attr_len;
   436→        }
   437→
   438→        offset += SIZEOF(uint32_t);
   439→        payload = data + offset;
   440→
   441→        // handle event
   442→        return __handle_event(client, &attr_info.value.event, payload);
   443→    } else {
   444→        PR_ERR("unsupported packet type: %d", type);
   445→        return OPRT_NOT_SUPPORTED;
   446→    }
   447→}
