   449→static int __find_sync_frame(const uint8_t *data, uint32_t len)
   450→{
   451→    // Search for magic number
   452→    uint32_t magic = UNI_HTONL(AI_MONITOR_MAGIC);
   453→    for (uint32_t offset = 0; offset <= len; offset++) {
   454→        if (memcmp(data + offset, &magic, sizeof(magic)) == 0) {
   455→            return offset; // Found sync frame
   456→        }
   457→    }
   458→    return OPRT_NOT_FOUND; // No valid frame found
   459→}
