   461→/**
   462→ * @brief Socket read handler
   463→ */
   464→static void __socket_read_handler(int32_t sock)
   465→{
   466→    ai_monitor_client_t *client = __find_client_by_fd(sock);
   467→    if (!client) {
   468→        PR_ERR("client not found for fd=%d", sock);
   469→        return;
   470→    }
   471→
   472→    // FIXME: current only support event type with event type == 0xf000, need to handle other types
   473→    // Receive data
   474→    int recv_len =
   475→        tal_net_recv((const int)sock, client->recv_buf + client->recv_len, client->recv_buf_size - client->recv_len);
   476→    if (recv_len <= 0) {
   477→        if (recv_len == 0) {
   478→            PR_INFO("client fd=%d disconnected", sock);
   479→        } else {
   480→            PR_ERR("recv data failed, errno=%d", tal_net_get_errno());
   481→        }
   482→
   483→        tal_mutex_lock(g_ai_monitor_server.mutex);
   484→        // Cleanup client
   485→        __cleanup_client(client);
   486→        g_ai_monitor_server.client_count--;
   487→        tal_mutex_unlock(g_ai_monitor_server.mutex);
   488→        return;
   489→    }
   490→
   491→    client->recv_len += recv_len;
   492→
